#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <string>
using namespace std;

vector<int> prefixFunction(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    vector<int> pi = prefixFunction(s);
    int m = 0;
    for (int i = 0; i + 1 < n; i++) m = max(m, pi[i]);
    int k = pi[n - 1];
    while (k > m) k = pi[k - 1];
    cout << k << "\n";

    return 0;
}

